import sys, numpy as np
sys.path.insert(0,'/opt/tools');from rcb_client import Robot
r=Robot(); o=r.get_obs(video='none'); now=np.array(o.meta['proprio']['now']);q0=now[:7]
u=np.array([.89,.45,0.]);u=u/np.linalg.norm(u); y=np.array([-.45,.89,0.]);y=y/np.linalg.norm(y);z=-u;x=np.cross(y,z);x/=np.linalg.norm(x);R=np.column_stack([x,y,z]);
def quat(R):
 t=np.trace(R)
 if t>0:
  s=np.sqrt(t+1)*2; w=.25*s; xq=(R[2,1]-R[1,2])/s; yq=(R[0,2]-R[2,0])/s; zq=(R[1,0]-R[0,1])/s
 else: raise ValueError(t)
 return np.array([w,xq,yq,zq])
qq=quat(R);print('R',R,'q',qq,'det',np.linalg.det(R),'now',now[22:29])
for xyz in [[7.51,3.89,.79],[7.40,3.83,.79],[7.4,3.83,.82]]:
 ans=r.ik({'gripper':[*xyz,*qq]},seed=q0);print(xyz,ans)
PY

